use std::{
    sync::{Arc, Mutex},
    time::Duration,
};

use ruapc_memory::BufferSet;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::{
    Buffer, BufferAvailability, Context, Error,
    remote_memory::{ReadSource, WriteTarget},
};

use super::{Client, ReadAttachment};

/// A client wrapper that borrows read sources and attaches write destinations.
///
/// Created via [`Client::with_read_buffers`] /
/// [`Client::with_write_buffers`] / [`Client::with_write_buffers_mut`].
/// Implements the same service traits as `Client` (generated by the
/// `#[service]` macro).
///
/// # Read buffers
///
/// Read attachments are reusable immutable sources for [`Context::remote_read`].
/// This wrapper borrows them; each request future performs inline copies and
/// post-READ validation while holding that borrow. The caller retains ownership
/// and can reuse the sources once the borrow ends.
///
/// # Owned write buffers
///
/// The next call consumes the attached write space, which the server fills
/// via [`Context::remote_write`]. When the call ends, the server can no longer
/// write, and the set is returned unless an RDMA READ still owns it: in-flight
/// RDMA retains destination ownership through completion or QP destruction.
/// A successful `Result<BufferReply<T>, E>` carries the set; after an error or
/// a plain result, use [`take_write_buffers`](Self::take_write_buffers). An
/// available set left in the wrapper is attached again by its next call.
/// Enable [`wait_for_write_buffers`](Self::wait_for_write_buffers) to also
/// wait for such a READ, which guarantees destination recovery when the call
/// is polled to completion.
///
/// # Lent write buffers
///
/// [`with_write_buffers_mut`](Self::with_write_buffers_mut) lends the wrapper
/// caller-owned slots instead. A call moves each buffer out of its slot,
/// leaving an empty buffer (capacity 0) behind, and moves the original back
/// before it returns, with any result: it always waits for a READ that still
/// owns the set, as with [`wait_for_write_buffers`](Self::wait_for_write_buffers).
/// The slots are then attached again to the wrapper's next call.
///
/// Only a call that is not polled to completion can leave its slots empty.
/// Dropping it restores them when that needs no waiting. A call dropped while
/// a READ owns the set, or while it already waits for one, leaves them empty;
/// the pool reclaims the originals once the READ settles. Forgetting a call
/// restores nothing and leaks the originals. In no case do the slots alias
/// memory that a READ can still write.
///
/// # Examples
///
/// ```rust,ignore
/// // Upload and download in a single call:
/// let (rsp, out) = client
///     .with_read_buffers(&src_bufs)
///     .with_write_buffers(dst_bufs)
///     .transform(&ctx, &req)
///     .await?
///     .into_parts();
///
/// // Download into caller-owned slots:
/// client.with_write_buffers_mut(&mut dst_bufs).download(&ctx, &req).await?;
/// ```
pub struct ClientWithBuffers<'a> {
    client: &'a Client,
    read_source: Option<ReadSource<'a>>,
    read_charge_bytes: Option<u64>,
    write: Mutex<WriteAttachment<'a>>,
    write_buffer_grace: Option<Duration>,
}

/// Write destinations for the wrapper's next call.
enum WriteAttachment<'a> {
    /// An owned set and its recovery state.
    Owned(BufferAvailability),
    /// Lent slots; `None` while a call holds them or after a call failed to
    /// restore them.
    Lent(Option<&'a mut [Buffer]>),
}

impl<'a> WriteAttachment<'a> {
    /// Hands the destinations to one call.
    fn check_out(&mut self) -> Option<CheckedOut<'a>> {
        match self {
            Self::Owned(BufferAvailability::Available(buffers)) => {
                let buffers = std::mem::take(buffers);
                // A call dropped before it returns leaves the set unavailable.
                *self = Self::Owned(BufferAvailability::Unavailable);
                Some(CheckedOut::Owned(buffers))
            }
            Self::Lent(slots) => slots.take().map(CheckedOut::Lent),
            Self::Owned(_) => None,
        }
    }
}

enum CheckedOut<'a> {
    Owned(Vec<Buffer>),
    Lent(&'a mut [Buffer]),
}

/// Lent slots whose buffers a call's write target holds.
///
/// Once every buffer is back in its slot, the slots are lent to the wrapper's
/// next call again. Dropping the guard restores them unless a READ still owns
/// the buffers at that point, or `restore` has already sealed the target to
/// wait for one: its recovery receiver is then dropped with the wait.
struct LentSlots<'w, 'a> {
    attachment: &'w Mutex<WriteAttachment<'a>>,
    slots: &'a mut [Buffer],
    target: Arc<WriteTarget>,
}

impl<'w, 'a> LentSlots<'w, 'a> {
    fn new(attachment: &'w Mutex<WriteAttachment<'a>>, slots: &'a mut [Buffer]) -> Self {
        let buffers = slots.iter_mut().map(Buffer::take).collect();
        Self {
            attachment,
            slots,
            target: WriteTarget::new(BufferSet::new(buffers)),
        }
    }

    /// Seals the target, waits for any READ, and restores every slot.
    async fn restore(mut self, grace: Duration) {
        let buffers = self.target.seal(Some(grace)).await;
        self.put_back(buffers.expect("only the original call seals its target"));
    }

    fn put_back(&mut self, buffers: Vec<Buffer>) {
        // A READ returns the original vector, so positions are unchanged.
        debug_assert_eq!(buffers.len(), self.slots.len());
        for (slot, buffer) in self.slots.iter_mut().zip(buffers) {
            *slot = buffer;
        }
        let slots = std::mem::take(&mut self.slots);
        *self.attachment.lock().unwrap() = WriteAttachment::Lent(Some(slots));
    }
}

impl Drop for LentSlots<'_, '_> {
    fn drop(&mut self) {
        // `None` once `restore` has sealed the target.
        if let Some(buffers) = self.target.seal_now() {
            self.put_back(buffers);
        }
    }
}

impl<'a> ClientWithBuffers<'a> {
    /// Creates an empty wrapper; see [`Client::with_read_buffers`] /
    /// [`Client::with_write_buffers`].
    pub(super) fn new(client: &'a Client) -> Self {
        Self {
            client,
            read_source: None,
            read_charge_bytes: None,
            write: Mutex::new(WriteAttachment::Owned(BufferAvailability::NotAttached)),
            write_buffer_grace: None,
        }
    }

    /// Replaces the request's read space with one borrowed buffer.
    #[must_use]
    pub fn with_read_buffer(self, buffer: &'a Buffer) -> Self {
        self.with_read_buffers(std::slice::from_ref(buffer))
    }

    /// Replaces the request's read space with borrowed buffers.
    ///
    /// Construction is infallible; requests check the region limit before
    /// acquiring a connection or publishing the buffers.
    #[must_use]
    pub fn with_read_buffers(mut self, buffers: &'a [Buffer]) -> Self {
        self.read_source = Some(ReadSource::new(buffers));
        self
    }

    /// Returns an immutable view of the attached source buffers.
    pub fn read_buffers(&self) -> &[Buffer] {
        self.read_source
            .as_ref()
            .map_or(&[], |source| source.buffers())
    }

    /// Overrides the SEND bandwidth charge for an internal request whose
    /// peer will read only part of the advertised read space.
    #[cfg(feature = "rdma")]
    pub(crate) fn with_read_charge_bytes(mut self, bytes: u64) -> Self {
        self.read_charge_bytes = Some(bytes);
        self
    }

    /// Attaches owned write buffers, replacing any previous write attachment.
    #[must_use]
    pub fn with_write_buffers(self, buffers: Vec<Buffer>) -> Self {
        *self.write.lock().unwrap() =
            WriteAttachment::Owned(BufferAvailability::Available(buffers));
        self
    }

    /// Lends one write buffer; see [`Self::with_write_buffers_mut`].
    #[must_use]
    pub fn with_write_buffer_mut(self, buffer: &'a mut Buffer) -> Self {
        self.with_write_buffers_mut(std::slice::from_mut(buffer))
    }

    /// Lends write buffers to the wrapper's calls, replacing any previous
    /// write attachment.
    ///
    /// Each call that returns, with any result, has moved the original buffers
    /// back into their slots, waiting without a time limit for any READ that
    /// still owns them. That wait follows
    /// [`wait_for_write_buffers`](Self::wait_for_write_buffers), including
    /// closing the READ's connection after the grace period; the grace is
    /// [`Client::timeout`] if unset. After an error, the restored bytes are not
    /// a valid transfer result.
    ///
    /// The slots are the only way back: a `BufferReply` and
    /// [`take_write_buffers`](Self::take_write_buffers) report `NotAttached`.
    /// Concurrent calls on the wrapper see no write attachment while one call
    /// holds the slots.
    ///
    /// A call that is not polled to completion can leave the slots empty.
    /// Dropping it, including cancellation by `select!` or a timeout wrapper,
    /// restores them only when that needs no waiting: not while a READ owns
    /// the buffers, nor once the call waits for one. Forgetting it never
    /// restores them and leaks the original buffers. Unrestored slots hold
    /// empty buffers ([`Buffer::capacity`] is 0) and are no longer attached to
    /// later calls.
    #[must_use]
    pub fn with_write_buffers_mut(self, buffers: &'a mut [Buffer]) -> Self {
        *self.write.lock().unwrap() = WriteAttachment::Lent(Some(buffers));
        self
    }

    /// Waits for the complete attached write-buffer set before returning a call.
    ///
    /// Without this option, a set that an RDMA READ still owns when the RPC
    /// ends is reported unavailable. With it, such a READ gets `grace` to
    /// return the buffers. If it remains outstanding, its RDMA connection is
    /// closed and recovery waits without a deadline for completion or
    /// successful QP destruction. Zero grace requests immediate closure.
    /// Closing a shared connection also fails other requests using it;
    /// existing connection watchdogs still apply. Lent write buffers always
    /// wait; this sets their grace.
    ///
    /// Recovery can exceed the RPC deadline and does not change its result or
    /// where the set is returned. Recovered bytes after an error are not valid
    /// transfer results.
    ///
    /// This applies only to write destinations, not borrowed read sources.
    /// It requires polling the call to completion: dropping or forgetting its
    /// future cannot guarantee recovery, and never releases in-flight DMA early.
    #[must_use]
    pub fn wait_for_write_buffers(mut self, grace: Duration) -> Self {
        self.write_buffer_grace = Some(grace);
        self
    }

    /// Takes an unused owned write-buffer set or one returned by a finished call.
    ///
    /// Distinguishes no attachment, an available set (including an empty set),
    /// and an unavailable set. A call returns its set here after an error or a
    /// successful plain `Result<T, E>`; a successful `BufferReply<T>` carries
    /// it instead. The set is unavailable if the call was dropped, or if an
    /// RDMA READ still owned it when the call ended without
    /// [`Self::wait_for_write_buffers`]; the QP then returns those buffers to
    /// the pool. Recovery permits reuse; after failure it does not establish
    /// valid transfer contents or promise that the buffers have been zeroed.
    /// Lent write buffers are reported as `NotAttached`.
    pub fn take_write_buffers(&self) -> BufferAvailability {
        match &mut *self.write.lock().unwrap() {
            WriteAttachment::Owned(availability) => availability.take(),
            WriteAttachment::Lent(_) => BufferAvailability::NotAttached,
        }
    }

    /// Makes an RPC request with the configured buffers.
    ///
    /// A successful buffer reply stores owned destinations in `reply_slot`.
    pub(crate) async fn ruapc_request<Req, Rsp, E>(
        &self,
        ctx: &Context,
        req: &Req,
        reply_slot: Option<&mut BufferAvailability>,
        method_name: &str,
    ) -> std::result::Result<Rsp, E>
    where
        Req: Serialize + JsonSchema,
        Rsp: for<'c> Deserialize<'c> + JsonSchema,
        E: std::error::Error + From<Error> + for<'c> Deserialize<'c>,
    {
        let checked_out = self.write.lock().unwrap().check_out();
        // Every path that attached a target seals it, so a reverse handler
        // that still holds it can no longer write.
        match checked_out {
            None => self.call(ctx, req, None, method_name).await,
            Some(CheckedOut::Owned(buffers)) => {
                let target = WriteTarget::new(BufferSet::new(buffers));
                let result = self.call(ctx, req, Some(&target), method_name).await;
                // The set is either back, or owned by a READ that only
                // `wait_for_write_buffers` waits for.
                let recovered = match target.seal(self.write_buffer_grace).await {
                    Some(buffers) => BufferAvailability::Available(buffers),
                    None => BufferAvailability::Unavailable,
                };
                // A successful buffer reply carries the set; otherwise it stays here.
                let remaining = match reply_slot {
                    Some(slot) if result.is_ok() => {
                        *slot = recovered;
                        BufferAvailability::NotAttached
                    }
                    _ => recovered,
                };
                *self.write.lock().unwrap() = WriteAttachment::Owned(remaining);
                result
            }
            Some(CheckedOut::Lent(slots)) => {
                let lent = LentSlots::new(&self.write, slots);
                let result = self.call(ctx, req, Some(&lent.target), method_name).await;
                let grace = self.write_buffer_grace.unwrap_or(self.client.timeout);
                lent.restore(grace).await;
                result
            }
        }
    }

    async fn call<Req, Rsp, E>(
        &self,
        ctx: &Context,
        req: &Req,
        target: Option<&Arc<WriteTarget>>,
        method_name: &str,
    ) -> std::result::Result<Rsp, E>
    where
        Req: Serialize + JsonSchema,
        Rsp: for<'c> Deserialize<'c> + JsonSchema,
        E: std::error::Error + From<Error> + for<'c> Deserialize<'c>,
    {
        self.client
            .ruapc_request(
                ctx,
                req,
                ReadAttachment::new(self.read_source.as_ref(), self.read_charge_bytes),
                target,
                method_name,
            )
            .await
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::client::tests::TestService;
    use crate::{
        BufferReply, ErrorKind, Message, MsgFlags, MsgMeta, Payload, Socket, SocketPoolConfig,
        msg::frame, tcp::TcpSocket,
    };
    use bytes::{Bytes, BytesMut};
    use ruapc_memory::MAX_REGIONS;

    #[tokio::test]
    async fn test_write_buffers_recoverable_after_failed_call() {
        let ctx = Context::create(&SocketPoolConfig::default()).unwrap();
        let client = Client::default();
        let mut buf = ctx.state.buffer_pool.allocate(64 * 1024).unwrap();
        buf.set_len(16);
        let wrapper = client.with_write_buffers(vec![buf]);
        // Invalid endpoint: the call fails before reaching the wire.
        let result = wrapper.test_call(&ctx, &()).await;
        assert!(result.is_err());
        let recovered = wrapper
            .take_write_buffers()
            .into_available()
            .expect("buffers recoverable");
        assert_eq!(recovered.len(), 1);
        assert_eq!(recovered[0].len(), 16);
    }

    #[crate::service]
    trait BufferedTest {
        async fn buffered(&self, ctx: &Context, req: &()) -> Result<BufferReply<u32>, Error>;
    }

    #[tokio::test]
    async fn calls_recover_destinations_and_revoke_stale_writers_on_every_result_path() {
        // Exercise both result contracts, application/framework errors,
        // decoding failure, and expiry with an already-routed writer alive,
        // with and without waiting for the destinations.
        for (outcome, buffered, grace) in (0..5).flat_map(|outcome| {
            [false, true].into_iter().flat_map(move |buffered| {
                [None, Some(Duration::ZERO)].map(|grace| (outcome, buffered, grace))
            })
        }) {
            let config = SocketPoolConfig {
                #[cfg(feature = "rdma")]
                rdma: None,
                ..Default::default()
            };
            let base = Context::create(&config).unwrap();
            let (sender, mut queue) = tokio::sync::mpsc::channel(1);
            let ctx = Context::server_ctx(
                &base.state,
                Socket::TCP(TcpSocket::new(sender)),
                MsgMeta {
                    timeout_ms: 5_000,
                    ..Default::default()
                },
            );
            let client = Client::default();
            let mut buffer = ctx.state.buffer_pool.allocate(4).unwrap();
            buffer.set_len(4);
            buffer.copy_from_slice(b"keep");
            let pointer = buffer.as_ptr();
            let mut wrapper = client.with_write_buffers(vec![buffer]);
            if let Some(grace) = grace {
                wrapper = wrapper.wait_for_write_buffers(grace);
            }
            let peer = async {
                let encoded = queue.recv().await.unwrap();
                let mut encoded = BytesMut::from(encoded.as_ref());
                let request =
                    Message::parse(frame::parse_message(&mut encoded).unwrap().unwrap()).unwrap();
                let retained = ctx
                    .state
                    .waiter
                    .write_target(request.meta.msgid, ctx.conn_id().unwrap())
                    .unwrap();
                if outcome == 4 {
                    ctx.state
                        .waiter
                        .expire(std::time::Instant::now() + Duration::from_secs(60));
                } else {
                    let response: Result<u32, Error> = if outcome == 0 {
                        Ok(7)
                    } else {
                        Err(Error::kind(ErrorKind::InvalidArgument))
                    };
                    let bytes = if outcome == 3 {
                        vec![0xc1]
                    } else {
                        rmp_serde::to_vec_named(&response).unwrap()
                    };
                    let mut flags = MsgFlags::UseMessagePack | MsgFlags::IsRsp;
                    if outcome == 2 {
                        flags |= MsgFlags::IsFrameworkError;
                    }
                    ctx.state.waiter.post(
                        request.meta.msgid,
                        Message::new(
                            MsgMeta {
                                msgid: request.meta.msgid,
                                flags,
                                ..Default::default()
                            },
                            Payload::from(Bytes::from(bytes)),
                        ),
                    );
                }
                retained
            };
            let mut destinations = BufferAvailability::NotAttached;
            let call = wrapper.ruapc_request::<(), u32, Error>(
                &ctx,
                &(),
                buffered.then_some(&mut destinations),
                "Test/recover",
            );
            let (result, retained) = tokio::join!(call, peer);
            assert_eq!(result.is_ok(), outcome == 0);
            if outcome == 4 {
                assert_eq!(result.unwrap_err().kind, ErrorKind::Timeout);
            }
            // A successful buffer reply carries the set; every other result
            // leaves it in the wrapper.
            let recovered = if outcome == 0 && buffered {
                assert!(matches!(
                    wrapper.take_write_buffers(),
                    BufferAvailability::NotAttached
                ));
                destinations
            } else {
                wrapper.take_write_buffers()
            }
            .into_available()
            .expect("a set no READ owns is always recovered");
            assert_eq!(recovered[0].as_ptr(), pointer);
            assert!(retained.copy_in(0, b"late").is_err());
            assert_eq!(recovered[0].as_slice(), b"keep");
        }
    }

    #[cfg(feature = "rdma")]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn only_waiting_calls_outlast_a_read_and_none_keeps_validating_sources() {
        use crate::rdma::test_utils::RdmaConnection;

        let connection = RdmaConnection::establish().await;
        for wait in [false, true] {
            let (sender, mut queue) = tokio::sync::mpsc::channel(1);
            let ctx = Context::server_ctx(
                &connection.context.state,
                Socket::TCP(TcpSocket::new(sender)),
                MsgMeta {
                    timeout_ms: 5_000,
                    ..Default::default()
                },
            );
            let source = ctx.state.buffer_pool.allocate(4).unwrap();
            let mut destination = ctx.state.buffer_pool.allocate(4).unwrap();
            destination.set_len(4);
            let pointer = destination.as_ptr();
            let client = Client::default();
            let mut wrapper = client
                .with_read_buffer(&source)
                .with_write_buffers(vec![destination]);
            if wait {
                wrapper = wrapper.wait_for_write_buffers(Duration::from_secs(30));
            }
            let mut call = Box::pin(wrapper.buffered(&ctx, &()));
            assert!(futures_util::poll!(call.as_mut()).is_pending());
            let encoded = queue.recv().await.unwrap();
            let mut encoded = BytesMut::from(encoded.as_ref());
            let request =
                Message::parse(frame::parse_message(&mut encoded).unwrap().unwrap()).unwrap();
            let (route, deadline) = ctx
                .state
                .waiter
                .read_source(request.meta.msgid, ctx.conn_id().unwrap())
                .unwrap();
            let target = ctx
                .state
                .waiter
                .write_target(request.meta.msgid, ctx.conn_id().unwrap())
                .unwrap();
            let posting = connection.hold(&target);
            ctx.state.waiter.expire(deadline);
            if wait {
                assert!(
                    futures_util::poll!(call.as_mut()).is_pending(),
                    "recovery still owns the pending call"
                );
                assert!(
                    route.is_closed(),
                    "recovery must not continue source validation"
                );
                assert_eq!(
                    route.validate(deadline).await.unwrap_err().kind,
                    ErrorKind::Timeout
                );
                drop(posting);
            }
            assert_eq!(call.await.unwrap_err().kind, ErrorKind::Timeout);
            let recovered = wrapper.take_write_buffers();
            if wait {
                assert_eq!(recovered.into_available().unwrap()[0].as_ptr(), pointer);
            } else {
                assert!(matches!(recovered, BufferAvailability::Unavailable));
            }
        }
        connection.shutdown().await;
    }

    #[tokio::test]
    async fn a_set_left_in_the_wrapper_is_attached_again_by_its_next_call() {
        let config = SocketPoolConfig {
            #[cfg(feature = "rdma")]
            rdma: None,
            ..Default::default()
        };
        let base = Context::create(&config).unwrap();
        let (sender, mut queue) = tokio::sync::mpsc::channel(1);
        let ctx = Context::server_ctx(
            &base.state,
            Socket::TCP(TcpSocket::new(sender)),
            MsgMeta {
                timeout_ms: 5_000,
                ..Default::default()
            },
        );
        let client = Client::default();
        let mut buffer = ctx.state.buffer_pool.allocate(4).unwrap();
        buffer.set_len(4);
        let pointer = buffer.as_ptr();
        let wrapper = client.with_write_buffers(vec![buffer]);
        // Writes into the destinations attached to one request, then answers it.
        let mut serve = async |data: &[u8], response: Vec<u8>| {
            let encoded = queue.recv().await.unwrap();
            let mut encoded = BytesMut::from(encoded.as_ref());
            let request =
                Message::parse(frame::parse_message(&mut encoded).unwrap().unwrap()).unwrap();
            ctx.state
                .waiter
                .write_target(request.meta.msgid, ctx.conn_id().unwrap())
                .expect("the call attached the set held by its wrapper")
                .copy_in(0, data)
                .unwrap();
            ctx.state.waiter.post(
                request.meta.msgid,
                Message::new(
                    MsgMeta {
                        msgid: request.meta.msgid,
                        flags: MsgFlags::UseMessagePack | MsgFlags::IsRsp,
                        ..Default::default()
                    },
                    Payload::from(Bytes::from(response)),
                ),
            );
        };

        // Neither a successful plain result nor an error consumes the set:
        // without `take_write_buffers`, the following call writes into it.
        let plain: Result<(), Error> = Ok(());
        let (result, ()) = tokio::join!(
            wrapper.test_call(&ctx, &()),
            serve(b"one.", rmp_serde::to_vec_named(&plain).unwrap())
        );
        result.unwrap();
        let failed: Result<(), Error> = Err(Error::kind(ErrorKind::InvalidArgument));
        let (result, ()) = tokio::join!(
            wrapper.test_call(&ctx, &()),
            serve(b"two.", rmp_serde::to_vec_named(&failed).unwrap())
        );
        assert_eq!(result.unwrap_err().kind, ErrorKind::InvalidArgument);

        // A successful buffer reply finally takes the set out of the wrapper.
        let buffered: Result<u32, Error> = Ok(7);
        let (reply, ()) = tokio::join!(
            wrapper.buffered(&ctx, &()),
            serve(b"last", rmp_serde::to_vec_named(&buffered).unwrap())
        );
        let (response, destinations) = reply.unwrap().into_parts();
        assert_eq!(response, 7);
        let buffers = destinations.into_available().unwrap();
        assert_eq!(buffers[0].as_ptr(), pointer);
        assert_eq!(buffers[0].as_slice(), b"last");
        assert!(matches!(
            wrapper.take_write_buffers(),
            BufferAvailability::NotAttached
        ));
    }

    #[tokio::test]
    async fn unsent_calls_preserve_empty_and_invalid_attachments() {
        let ctx = Context::create(&SocketPoolConfig::default()).unwrap();
        let client = Client::default();
        for (count, grace) in [0, MAX_REGIONS + 1]
            .into_iter()
            .flat_map(|count| [None, Some(Duration::ZERO)].map(|grace| (count, grace)))
        {
            let buffers = (0..count)
                .map(|_| Buffer::empty(&ctx.state.buffer_pool))
                .collect();
            let mut wrapper = client.with_write_buffers(buffers);
            if let Some(grace) = grace {
                wrapper = wrapper.wait_for_write_buffers(grace);
            }
            assert!(wrapper.test_call(&ctx, &()).await.is_err());
            assert_eq!(
                wrapper.take_write_buffers().into_available().unwrap().len(),
                count
            );
        }
    }

    #[tokio::test]
    async fn failed_call_preserves_attached_empty_destinations() {
        let ctx = Context::create(&SocketPoolConfig::default()).unwrap();
        let client = Client::default();
        let wrapper = client.with_write_buffers(Vec::new());
        assert!(wrapper.test_call(&ctx, &()).await.is_err());
        assert!(
            matches!(wrapper.take_write_buffers(), BufferAvailability::Available(buffers) if buffers.is_empty())
        );
        assert!(matches!(
            wrapper.take_write_buffers(),
            BufferAvailability::NotAttached
        ));
    }

    #[tokio::test]
    async fn invalid_attachments_preserve_the_supplied_buffers() {
        let ctx = Context::create(&SocketPoolConfig::default()).unwrap();
        let client = Client::default();
        let buffers: Vec<_> = (0..=MAX_REGIONS)
            .map(|_| Buffer::empty(&ctx.state.buffer_pool))
            .collect();
        let pointer = buffers[0].as_ptr();
        let mut destination = ctx.state.buffer_pool.allocate(4).unwrap();
        destination.set_len(4);
        destination.copy_from_slice(b"keep");
        let destination_pointer = destination.as_ptr();
        let wrapper = client
            .with_read_buffers(&buffers)
            .with_write_buffers(vec![destination]);
        assert_eq!(wrapper.read_buffers().len(), MAX_REGIONS + 1);
        // The context has no endpoint: attachment validation must precede
        // connection acquisition, and preserve both borrowed and owned memory.
        let error = wrapper.test_call(&ctx, &()).await.unwrap_err();
        assert_eq!(error.kind, ErrorKind::InvalidCopyOp);
        assert_eq!(buffers.len(), MAX_REGIONS + 1);
        assert_eq!(buffers[0].as_ptr(), pointer);
        let recovered = wrapper.take_write_buffers().into_available().unwrap();
        assert_eq!(recovered[0].as_ptr(), destination_pointer);
        assert_eq!(recovered[0].as_slice(), b"keep");

        // The next call must validate only the replacement attachment.
        let wrapper = wrapper.with_read_buffer(&buffers[0]);
        assert_eq!(wrapper.read_buffers().len(), 1);
        assert_eq!(
            wrapper.test_call(&ctx, &()).await.unwrap_err().kind,
            ErrorKind::InvalidArgument
        );

        let wrapper = client.with_write_buffers(buffers);
        let error = wrapper.test_call(&ctx, &()).await.unwrap_err();
        assert_eq!(error.kind, ErrorKind::InvalidCopyOp);
        let buffers = wrapper.take_write_buffers().into_available().unwrap();
        assert_eq!(buffers.len(), MAX_REGIONS + 1);
        assert_eq!(buffers[0].as_ptr(), pointer);
    }

    /// A context whose outgoing requests the test receives and answers itself.
    fn queued_context() -> (Context, tokio::sync::mpsc::Receiver<Bytes>) {
        let config = SocketPoolConfig {
            #[cfg(feature = "rdma")]
            rdma: None,
            ..Default::default()
        };
        let base = Context::create(&config).unwrap();
        let (sender, queue) = tokio::sync::mpsc::channel(1);
        let ctx = Context::server_ctx(
            &base.state,
            Socket::TCP(TcpSocket::new(sender)),
            MsgMeta {
                timeout_ms: 5_000,
                ..Default::default()
            },
        );
        (ctx, queue)
    }

    fn lent_buffer(ctx: &Context, bytes: &[u8]) -> Buffer {
        let mut buffer = ctx.state.buffer_pool.allocate(bytes.len()).unwrap();
        buffer.set_len(bytes.len());
        buffer.copy_from_slice(bytes);
        buffer
    }

    /// Receives one request and returns its message id.
    async fn next_request(queue: &mut tokio::sync::mpsc::Receiver<Bytes>) -> u64 {
        let encoded = queue.recv().await.unwrap();
        let mut encoded = BytesMut::from(encoded.as_ref());
        Message::parse(frame::parse_message(&mut encoded).unwrap().unwrap())
            .unwrap()
            .meta
            .msgid
    }

    fn respond<T: Serialize>(ctx: &Context, msgid: u64, response: &Result<T, Error>) {
        ctx.state.waiter.post(
            msgid,
            Message::new(
                MsgMeta {
                    msgid,
                    flags: MsgFlags::UseMessagePack | MsgFlags::IsRsp,
                    ..Default::default()
                },
                Payload::from(Bytes::from(rmp_serde::to_vec_named(response).unwrap())),
            ),
        );
    }

    #[tokio::test]
    async fn lent_slots_are_restored_and_lent_again_after_every_result() {
        let (ctx, mut queue) = queued_context();
        let client = Client::default();
        let mut slots = [lent_buffer(&ctx, b"ab"), lent_buffer(&ctx, b"cd")];
        let pointers = slots.each_ref().map(|buffer| buffer.as_ptr());
        {
            let wrapper = client.with_write_buffers_mut(&mut slots);
            for (data, response) in [
                (b"one.", Ok(7)),
                (b"two.", Err(Error::kind(ErrorKind::InvalidArgument))),
            ] {
                let serve = async {
                    let msgid = next_request(&mut queue).await;
                    let target = ctx
                        .state
                        .waiter
                        .write_target(msgid, ctx.conn_id().unwrap())
                        .unwrap();
                    target.copy_in(0, data).unwrap();
                    respond(&ctx, msgid, &response);
                    target
                };
                let (reply, stale) = tokio::join!(wrapper.buffered(&ctx, &()), serve);
                // Lent slots never travel with the reply or the wrapper.
                match reply {
                    Ok(reply) => assert!(matches!(
                        reply.destinations(),
                        BufferAvailability::NotAttached
                    )),
                    Err(error) => assert_eq!(error.kind, ErrorKind::InvalidArgument),
                }
                assert!(matches!(
                    wrapper.take_write_buffers(),
                    BufferAvailability::NotAttached
                ));
                assert!(stale.copy_in(0, b"late").is_err());
            }
        }
        assert_eq!(slots.each_ref().map(|buffer| buffer.as_ptr()), pointers);
        assert_eq!([&*slots[0], &*slots[1]], [b"tw", b"o."]);
    }

    #[tokio::test]
    async fn dropped_calls_restore_lent_slots_and_forgotten_calls_empty_them() {
        let (ctx, mut queue) = queued_context();
        let client = Client::default();
        let mut slot = lent_buffer(&ctx, b"keep");
        let pointer = slot.as_ptr();
        {
            let wrapper = client.with_write_buffer_mut(&mut slot);
            let mut call = Box::pin(wrapper.test_call(&ctx, &()));
            assert!(futures_util::poll!(call.as_mut()).is_pending());
            let msgid = next_request(&mut queue).await;
            let stale = ctx
                .state
                .waiter
                .write_target(msgid, ctx.conn_id().unwrap())
                .unwrap();
            drop(call);
            assert!(stale.copy_in(0, b"late").is_err());

            // The dropped call lends the slot again; a forgotten one keeps it.
            let mut call = Box::pin(wrapper.test_call(&ctx, &()));
            assert!(futures_util::poll!(call.as_mut()).is_pending());
            next_request(&mut queue).await;
            std::mem::forget(call);
            let mut call = Box::pin(wrapper.test_call(&ctx, &()));
            assert!(futures_util::poll!(call.as_mut()).is_pending());
            let msgid = next_request(&mut queue).await;
            assert!(
                ctx.state
                    .waiter
                    .write_target(msgid, ctx.conn_id().unwrap())
                    .is_none(),
                "no slots remain to attach"
            );
        }
        assert_eq!((slot.len(), slot.capacity()), (0, 0));
        assert_ne!(slot.as_ptr(), pointer);
    }

    #[tokio::test]
    async fn unsent_calls_restore_invalid_lent_slots() {
        let ctx = Context::create(&SocketPoolConfig::default()).unwrap();
        let client = Client::default();
        let mut slots: Vec<_> = (0..=MAX_REGIONS).map(|_| lent_buffer(&ctx, b"x")).collect();
        let pointer = slots[0].as_ptr();
        let wrapper = client.with_write_buffers_mut(&mut slots);
        let error = wrapper.test_call(&ctx, &()).await.unwrap_err();
        assert_eq!(error.kind, ErrorKind::InvalidCopyOp);
        drop(wrapper);
        assert_eq!(slots[0].as_ptr(), pointer);
        assert_eq!(&*slots[MAX_REGIONS], b"x");
    }

    #[cfg(feature = "rdma")]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn lent_calls_outlast_a_read_unless_dropped() {
        use crate::rdma::test_utils::RdmaConnection;

        let connection = RdmaConnection::establish().await;
        for drop_call in [false, true] {
            let (sender, mut queue) = tokio::sync::mpsc::channel(1);
            let ctx = Context::server_ctx(
                &connection.context.state,
                Socket::TCP(TcpSocket::new(sender)),
                MsgMeta {
                    timeout_ms: 5_000,
                    ..Default::default()
                },
            );
            let mut slot = lent_buffer(&ctx, b"keep");
            let pointer = slot.as_ptr();
            let client = Client::default();
            {
                let wrapper = client
                    .with_write_buffer_mut(&mut slot)
                    .wait_for_write_buffers(Duration::from_secs(30));
                let mut call = Box::pin(wrapper.test_call(&ctx, &()));
                assert!(futures_util::poll!(call.as_mut()).is_pending());
                let msgid = next_request(&mut queue).await;
                let target = ctx
                    .state
                    .waiter
                    .write_target(msgid, ctx.conn_id().unwrap())
                    .unwrap();
                let posting = connection.hold(&target);
                respond(&ctx, msgid, &Ok(()));
                assert!(futures_util::poll!(call.as_mut()).is_pending());
                if drop_call {
                    // The READ keeps the buffer; the pool reclaims it later.
                    drop(call);
                    drop(posting);
                } else {
                    drop(posting);
                    call.await.unwrap();
                }
            }
            if drop_call {
                assert_eq!(slot.capacity(), 0);
            } else {
                assert_eq!(slot.as_ptr(), pointer);
                assert_eq!(&*slot, b"keep");
            }
        }
        connection.shutdown().await;
    }
}
